// Hook into Firebase ready event to load phrases
onFirebaseReady(function() {
  loadPhrasesFromFirebase();
  loadQpacketFromFirebase();
});

function loadPhrasesFromFirebase(){
  if(!FIREBASE_DB)return;
  FIREBASE_DB.collection("offspec").doc("phrases").get().then(function(doc){
    var st=document.getElementById("fbStatus");
    if(doc.exists){
      var data=doc.data();
      if(Array.isArray(data.list)){
        MISC_PHRASES.length=0;
        data.list.forEach(function(x){MISC_PHRASES.push(x);});
        updateNotifButton();
        var ra=document.getElementById("reasonArea");
        if(ra){
          ra.querySelectorAll("[data-mls]").forEach(function(sel){
            var cur=sel.value;
            var opts='<option value="">— phrases —</option>';
            MISC_PHRASES.forEach(function(item){
              var kw=item.k||item.p||"";var ph=item.p||item.k||"";
              opts+='<option value="'+ph.replace(/"/g,"&quot;")+'">'+kw+'</option>';
            });
            sel.innerHTML=opts;sel.value=cur;
          });
        }
        if(document.getElementById("phraseModal")&&document.getElementById("phraseModal").style.display==="flex"){
          renderPhraseList();
        }
        if(st){st.style.color="#4caf50";st.textContent="&#9679; Phrases synced ("+(MISC_PHRASES.length)+" loaded)";}
      }
    }else{
      if(st){st.style.color="#888";st.textContent="&#9679; Firebase connected (no phrases yet)";}
    }
  }).catch(function(e){
    console.warn("Firebase read error:",e);
    var st=document.getElementById("fbStatus");
    if(st){st.style.color="#f44336";st.textContent="&#9679; Sync error — working offline";}
  });
}

function savePhrases(){
  if(!FIREBASE_DB){updateNotifButton();return;}
  FIREBASE_DB.collection("offspec").doc("phrases").set({list:MISC_PHRASES}).then(function(){
    updateNotifButton();
  }).catch(function(e){showToast("Error saving phrases: "+e.message,"error");});
}

function loadQpacketFromFirebase(){
  if(!FIREBASE_DB)return;
  FIREBASE_DB.collection("offspec").doc("qpacket").get().then(function(doc){
    if(doc.exists){
      var data=doc.data()||{};
      QPACKET.instr=(data.instr&&typeof data.instr==='object'&&!Array.isArray(data.instr))?data.instr:{};
      QPACKET.kw=Array.isArray(data.kw)?data.kw.slice():DEFAULT_PHOTO_KEYWORDS.slice();
      QPACKET.alerts=Array.isArray(data.alerts)?data.alerts.slice():DEFAULT_KEYWORD_ALERTS.map(function(a){return {kw:a.kw,msg:a.msg};});
    }else{
      QPACKET.instr={};
      QPACKET.kw=DEFAULT_PHOTO_KEYWORDS.slice();
      QPACKET.alerts=DEFAULT_KEYWORD_ALERTS.map(function(a){return {kw:a.kw,msg:a.msg};});
    }
    var modal=document.getElementById("phraseModal");
    if(modal&&modal.style.display==="flex"){if(typeof renderQpacketGuide==='function')renderQpacketGuide();}
  }).catch(function(e){console.warn("Firebase qpacket read error:",e);});
}
function saveQpacket(){
  if(!FIREBASE_DB)return;
  FIREBASE_DB.collection("offspec").doc("qpacket").set({instr:QPACKET.instr,kw:QPACKET.kw,alerts:QPACKET.alerts}).catch(function(e){showToast("Error saving Q-packet guide: "+e.message,"error");});
}
function getActivePhotoKeywords(){
  var k=(QPACKET&&QPACKET.kw&&QPACKET.kw.length)?QPACKET.kw.slice():DEFAULT_PHOTO_KEYWORDS.slice();
  return k.map(function(s){return (s||'').toString().toLowerCase().trim();}).filter(function(s){return !!s;});
}
function getSelectedLineDetails(){
  var out=[];if(!S.md||!S.md.li)return out;
  S.md.li.forEach(function(ln,i){if(S.sl[i])out.push(ln);});
  return out;
}
function getCurrentNotifCodes(){
  var codes=[];(S.mc||[]).forEach(function(c){c=(c||'').trim();if(c&&codes.indexOf(c)===-1)codes.push(c);});
  return codes;
}
function getActiveMiscLines(){
  // Returns non-empty user-typed Miscellaneous reason lines as [{idx,text,code}]
  // idx is 1-indexed for display.
  var out=[];
  (S.ml||[]).forEach(function(text,i){
    var t=(text||'').toString().trim();
    if(t)out.push({idx:i+1,text:t,code:((S.mc||[])[i]||'').trim()});
  });
  return out;
}
function detectPhotoTriggers(miscLines){
  var kws=getActivePhotoKeywords(),hits=[];
  miscLines.forEach(function(ml){
    var hay=ml.text.toLowerCase();
    kws.forEach(function(k){if(k&&hay.indexOf(k)!==-1)hits.push({idx:ml.idx,trigger:k});});
  });
  var seen={},dedup=[];
  hits.forEach(function(h){var key=h.idx+'|'+h.trigger;if(!seen[key]){seen[key]=true;dedup.push(h);}});
  return dedup;
}
function getOver10Lines(lines){
  return lines.filter(function(ln){var n=parseInt(ln.cont,10);return !isNaN(n)&&n>=10;});
}
function detectKeywordAlerts(miscLines){
  var alerts=(QPACKET&&Array.isArray(QPACKET.alerts))?QPACKET.alerts:[];
  if(!alerts.length)return [];
  var hits=[];
  miscLines.forEach(function(ml){
    var hay=ml.text.toLowerCase();
    alerts.forEach(function(a){
      var k=((a&&a.kw)||'').toString().toLowerCase().trim();
      if(!k)return;
      if(hay.indexOf(k)!==-1)hits.push({idx:ml.idx,kw:k,msg:(a.msg||'').toString()});
    });
  });
  // dedupe by misc-idx|kw|msg
  var seen={},dedup=[];
  hits.forEach(function(h){var key=h.idx+'|'+h.kw+'|'+h.msg;if(!seen[key]){seen[key]=true;dedup.push(h);}});
  return dedup;
}

