function m2i(s){var m=s.match(/(\d{2})\/(\d{2})\/(\d{4})/);return m?m[3]+"-"+m[1]+"-"+m[2]:s}

// Fix short year entries on date inputs
// If year < 100, try 2000+yr — if not within ±1 year of now, use current year
function fixDateYear(el) {
  if (!el || !el.value) return;
  var parts = el.value.split('-');
  if (parts.length === 3) {
    var yr = parseInt(parts[0], 10);
    var now = new Date().getFullYear();
    if (yr > 0 && yr < 100) {
      var candidate = 2000 + yr;
      if (Math.abs(candidate - now) <= 1) { parts[0] = '' + candidate; }
      else { parts[0] = '' + now; }
      el.value = parts.join('-');
    } else if (yr >= 100 && yr < 2020) {
      parts[0] = '' + now;
      el.value = parts.join('-');
    }
  }
}
// Global backup — catches any date input not explicitly handled
document.addEventListener('change', function(e) {
  if (e.target && e.target.type === 'date') fixDateYear(e.target);
});

// ── PDF parsing ──
async function exTxt(buf){
  var pdf=await pdfjsLib.getDocument({data:buf}).promise,ft="";
  for(var i=1;i<=pdf.numPages;i++){
    var pg=await pdf.getPage(i),c=await pg.getTextContent();
    var items=c.items.map(function(x){return{t:x.str,x:x.transform[4],y:Math.round(x.transform[5])}});
    items.sort(function(a,b){return b.y-a.y||a.x-b.x});
    var ls=[],cl=[],cy=null;
    for(var j=0;j<items.length;j++){var it=items[j];if(cy===null||Math.abs(it.y-cy)>3){if(cl.length)ls.push(cl);cl=[it];cy=it.y}else cl.push(it)}
    if(cl.length)ls.push(cl);
    for(var li=0;li<ls.length;li++){var ln=ls[li];ln.sort(function(a,b){return a.x-b.x});var t="",lx=0;for(var k=0;k<ln.length;k++){var g=ln[k].x-lx;if(g>10&&t.length)t+="   ";else if(g>3&&t.length)t+=" ";t+=ln[k].t;lx=ln[k].x+(ln[k].t.length*4)}ft+=t+"\n"}ft+="\n"}
  return ft;
}

function parseLSR(txt){
  var lm=txt.match(/Load\s*No\.?:?\s*(L\d+)/i),lr=lm?lm[1]:"",ln=lr.replace(/^L0*/,"");
  if(ln.length>5)ln=ln.slice(-5);
  var sx=/Sales\s*Doc\.?\s*(\d+)/g,m,ss=[];
  while((m=sx.exec(txt))!==null)ss.push({s:m[1],i:m.index});
  var mm={},mnOrder=[];
  var dataRe=/^\s*(\d+)\s+(\S+)\s+(\d+)\/(\d+)\s+(\S+)/;
  var skipRe=/^(Waste\b|Item\b|Manifest\b|Stream\b|Gro\b|cont\b|Proc\b|CD\b|Sales\b|Total\b|#\s*of\b|Type\b|Weight\b|Sample\b|Fac\b|Note\b|PLN\b|Rec\b|\d+\/\d+\/\d{4}\s+\d)/i;
  var timeRe=/\d{1,2}:\d{2}:\d{2}\s*(AM|PM)/i;
  var wrappedRe=/^\s*(\d+)\s+(\d+)\s+(DM|DF|CF|TP)\s+(\S+)/;
  var inlineRe=/^\s*(\d+)\s+(.+?)\s+(\d+)\s+(DM|DF|CF|TP)\s+(\S+)/;
  var afterRe=/(?:\s+(Y))?(?:\s+(S\d+\S*))?/;

  for(var i=0;i<ss.length;i++){
    var st=ss[i].i,en=i+1<ss.length?ss[i+1].i:txt.length;
    var bl=txt.substring(st,en),sd=ss[i].s;
    var lines=bl.split("\n");

    for(var li=0;li<lines.length;li++){
      var dm=lines[li].match(dataRe);
      if(!dm)continue;
      var it=dm[1],mn=dm[2],pg=dm[3],line=dm[4],ws=dm[5];
      var rest=lines[li].substring(dm[0].length);
      var gn="",cont="",cType="",procCD="",weight="",sample="";
      var wm=rest.match(wrappedRe);
      var im=rest.match(inlineRe);

      if(wm){
        cont=wm[2];cType=wm[3];procCD=wm[4];
        if(procCD==="Y"){weight="Y";procCD="";}
        var aw=rest.substring(wm[0].length).match(afterRe);
        if(aw){if(!weight)weight=aw[1]||"";sample=aw[2]||"";}
        // Generator name from above/below lines
        var parts=[];
        for(var a=li-1;a>=Math.max(0,li-4);a--){
          var at=lines[a].trim();
          if(!at||at.length<2)continue;
          if(dataRe.test(at))break;
          if(skipRe.test(at))break;
          if(timeRe.test(at))break;
          parts.unshift(at);
          break;
        }
        for(var b=li+1;b<Math.min(lines.length,li+4);b++){
          var bt=lines[b].trim();
          if(!bt||bt.length<2)continue;
          if(dataRe.test(bt))break;
          if(skipRe.test(bt))break;
          if(timeRe.test(bt))break;
          parts.push(bt);
          break;
        }
        gn=parts.join(" ").trim();
      }else if(im){
        gn=im[2].trim();cont=im[3];cType=im[4];procCD=im[5];
        if(procCD==="Y"){weight="Y";procCD="";}
        var ai=rest.substring(im[0].length).match(afterRe);
        if(ai){if(!weight)weight=ai[1]||"";sample=ai[2]||"";}
      }else{
        // Fallback: old-style above/below scan for generator
        var above=[];
        for(var a2=li-1;a2>=Math.max(0,li-3);a2--){
          var at2=lines[a2].trim();
          if(!at2||at2.length<3)continue;
          if(dataRe.test(at2))break;
          if(skipRe.test(at2))break;
          if(timeRe.test(at2))break;
          if(/^\d+$/.test(at2))continue;
          above.unshift(at2.replace(/\s+/g," "));
        }
        var below=[];
        for(var b2=li+1;b2<Math.min(lines.length,li+4);b2++){
          var bt2=lines[b2].trim();
          if(!bt2||bt2.length<3)continue;
          if(dataRe.test(bt2))break;
          if(skipRe.test(bt2))break;
          if(timeRe.test(bt2))break;
          if(/^\d+$/.test(bt2))continue;
          below.push(bt2.replace(/\s+/g," "));
        }
        gn=above.concat(below).join(" ").trim();
        gn=gn.replace(/\s*\d{2}\/\d{2}\/\d{4}.*$/,"").replace(/\s*S\d{9,}.*$/,"").trim();
      }

      var rdm2=lines[li].match(/(\d{2}\/\d{2}\/\d{4})/);
      var rd=rdm2?rdm2[1]:"";
      if(!rd){var rm2=bl.substring(bl.indexOf(lines[li])+lines[li].length,bl.indexOf(lines[li])+lines[li].length+400);var rdm=rm2.match(/(\d{2}\/\d{2}\/\d{4})/);rd=rdm?rdm[1]:"";}

      if(!mm[mn]){mm[mn]={mn:mn,sd:sd,g:"",li:[]};mnOrder.push(mn);}
      mm[mn].li.push({it:it,mn:mn,pg:pg,li:line,ws:ws,gn:gn,rd:rd,sd:sd,cont:cont,cType:cType,procCD:procCD,weight:weight,sample:sample});
      if(gn&&!mm[mn].g)mm[mn].g=gn;
    }
  }
  return{type:"lsr",ln:ln,lr:lr,mm:mm,mo:mnOrder};
}

function parseValidation(txt){
  var lm=txt.match(/Load\s*Number\s*(L\d+)/i);
  if(!lm)lm=txt.match(/Load\s*Number\s*\n\s*(L\d+)/i);
  var lr=lm?lm[1]:"",ln=lr.replace(/^L0*/,"");
  if(ln.length>5)ln=ln.slice(-5);
  var soRe=/Sales\s*Order\s+(\d+)/i;
  var mm={},mnOrder=[],so=[],curSO="";
  var rowRe=/^\s*(\d+)\s+(\S+)\/(\d+)\/(\d+)\s+(?:S\d+\s+)?(\d+)\s+(\S+)\s+(\S+)\s+(\S+)/;
  var lines=txt.split("\n");
  for(var i=0;i<lines.length;i++){
    var sm=lines[i].match(soRe);
    if(sm){curSO=sm[1];if(so.indexOf(curSO)<0)so.push(curSO);continue;}
    var rm=lines[i].match(rowRe);
    if(!rm)continue;
    var it=rm[1],mn=rm[2],pg=rm[3],lnv=rm[4],desc=rm[6],ws=rm[7];
    if(!mm[mn]){mm[mn]={mn:mn,sd:curSO,g:"",li:[]};mnOrder.push(mn);}
    mm[mn].li.push({it:it,mn:mn,pg:pg,li:lnv,ws:ws,gn:"",rd:"",sd:curSO,cont:"",cType:"",procCD:desc,weight:"",sample:""});
  }
  return{type:"validation",ln:ln,lr:lr,so:so,mm:mm,mo:mnOrder};
}

