// ── Paste from bookmarklet ──
document.getElementById("pasteBtn").onclick=async function(){
  var st=document.getElementById("st");
  try{
    var clip=await navigator.clipboard.readText();
    if(!clip||!clip.trim()){st.className="status err";st.textContent="Clipboard is empty — run the bookmarklet first";return}
    var data;
    try{data=JSON.parse(clip)}catch(e){st.className="status err";st.textContent="Clipboard doesn't contain valid bookmarklet data";return}
    if(!data||!data.mm){st.className="status err";st.textContent="Clipboard data missing required fields (ln, mm)";return}
    st.className="status wait";st.textContent="Loading from clipboard...";
    S.p=data;
    var cnt=Object.keys(S.p.mm).length;
    if(!cnt){st.className="status err";st.textContent="No manifests found in pasted data";return}
    var lbl=S.p.type==="validation"?"Validation Report":"LSR";st.className="status ok";st.textContent=(S.p.ln?"Load "+S.p.ln+" \u2014 ":"")+cnt+" manifest(s) from "+lbl+" bookmarklet";
    document.getElementById("dropTxt").textContent="\u2705 Loaded from bookmarklet";
    S.sm=null;S.sl={};S.blank=false;
    showSec("sec1");renderManifests();
  }catch(e){
    if(e.name==="NotAllowedError"){
      st.className="status err";st.textContent="Clipboard access denied — click the page first, then try again";
    }else{
      st.className="status err";st.textContent="Error reading clipboard: "+e.message;
    }
  }
};

// ── Auto-load from bookmarklet URL hash ──
(function(){
  var h=location.hash;
  if(!h||h.indexOf('#bm=')!==0)return;
  try{
    var json=decodeURIComponent(h.substring(4));
    var data=JSON.parse(json);
    if(!data||!data.mm)return;
    history.replaceState(null,'',location.pathname+location.search);
    var st=document.getElementById("st");
    S.p=data;
    var cnt=Object.keys(S.p.mm).length;
    if(!cnt){st.className="status err";st.textContent="No manifests found in bookmarklet data";return}
    var lbl=S.p.type==="validation"?"Validation Report":"LSR";
    st.className="status ok";st.textContent=(S.p.ln?"Load "+S.p.ln+" \u2014 ":"")+cnt+" manifest(s) from "+lbl+" bookmarklet";
    document.getElementById("dropTxt").textContent="\u2705 Loaded from bookmarklet";
    S.sm=null;S.sl={};S.blank=false;
    // Show manifests without touching top button layout
    document.getElementById("sec1").classList.add("show");
    renderManifests();
    // Success banner
    var banner=document.createElement("div");
    banner.style.cssText="position:fixed;top:0;left:0;right:0;z-index:99999;background:#1a5c2a;color:#fff;font-family:'Segoe UI',Arial,sans-serif;font-size:15px;font-weight:700;text-align:center;padding:14px 20px;box-shadow:0 2px 12px rgba(0,0,0,.4);";
    var names=Object.keys(S.p.mm).join(", ");
    banner.textContent="\u2705 "+cnt+" manifest(s) loaded from "+lbl+(S.p.ln?" \u2014 Load "+S.p.ln:"")+" \u2014 "+names;
    document.body.appendChild(banner);
    setTimeout(function(){banner.style.transition="opacity .5s";banner.style.opacity="0";setTimeout(function(){banner.remove()},600)},4000);
  }catch(e){console.warn("Hash load failed:",e)}
})();

