  S.wd=[{m:"",r:"",q:"",u:""},{m:"",r:"",q:"",u:""},{m:"",r:"",q:"",u:""},{m:"",r:"",q:"",u:""}];
  S.blank=true;
  showSec("sec3");renderForm();
  // Show blank line entry fields
