// Clear form — preserves Initials and Current Date
function clearOffspecForm(){
  // Clear standard fields
  var keep={"f3ini":true,"f3cd":true};
  ["aso","aln","amn","f3csr","f3gen","f3rd"].forEach(function(id){
    var el=document.getElementById(id);
    if(el)el.value="";
  });
  // Clear state
  S.go="";S.csr="";S.rd="";
  S.rs={};S.rl={};S.dt={};
  S.ml=["","",""];S.mc=["","",""];
  S.wd=[{m:"",r:"",q:"",u:""},{m:"",r:"",q:"",u:""},{m:"",r:"",q:"",u:""},{m:"",r:"",q:"",u:""}];
  // Clear parsed data references so preview doesn't show stale values
  S.sm=null;S.sl={};S.blank=false;
  if(S.md){S.md={mn:"",sd:"",g:"",li:[]};}
  if(S.p){S.p.ln="";}
  // Clear blank mode line inputs
  document.querySelectorAll("[data-blp],[data-bll],[data-blw]").forEach(function(el){el.value="";});
  // Re-render reasons and preview
  renderReasons();
  renderOffspecPreview();
  checkGenBtn();
  showToast("Form cleared","ok");
}
document.getElementById("genBtn").onclick=async function(){
  // Run validation first
  var missing=validateFields();
  if(missing.length>0){
    showToast("Missing required fields: "+missing.join(", "),"warn");
    return;
  }

  var btn=this;btn.disabled=true;btn.textContent="Generating...";
  try{
    // Decode template
    var bin=atob(TMPL_B64),arr=new Uint8Array(bin.length);
    for(var i=0;i<bin.length;i++)arr[i]=bin.charCodeAt(i);
    var zip=await JSZip.loadAsync(arr);

    // Read shared strings
    var ssXml=await zip.file("xl/sharedStrings.xml").async("string");
    var parser=new DOMParser();
    var ssDom=parser.parseFromString(ssXml,"text/xml");
    var NS="http://schemas.openxmlformats.org/spreadsheetml/2006/main";
    var siNodes=ssDom.getElementsByTagNameNS(NS,"si");
    var ssCount=siNodes.length;

    // Optional Line → Section relabel. Only swaps shared strings whose entire
    // text is exactly "Line" — the disclaimer's "MANIFEST LINE ITEM" is one
    // long shared string and won't match.
    if(S.lineLabel==="Section"){
      for(var ssi=0;ssi<siNodes.length;ssi++){
        var ssTs=siNodes[ssi].getElementsByTagNameNS(NS,"t");
        for(var ssj=0;ssj<ssTs.length;ssj++){
          if(ssTs[ssj].textContent==="Line")ssTs[ssj].textContent="Section";
        }
      }
    }

    // Helper: add a new shared string, return its index
    function addSS(text){
      var sst=ssDom.getElementsByTagNameNS(NS,"sst")[0];
      var si=ssDom.createElementNS(NS,"si");
      var t=ssDom.createElementNS(NS,"t");
      t.textContent=text;
      t.setAttribute("xml:space","preserve");
      si.appendChild(t);
      sst.appendChild(si);
      var idx=ssCount;ssCount++;
      // Update count attributes
      sst.setAttribute("count",""+(+sst.getAttribute("count")+1));
      sst.setAttribute("uniqueCount",""+ssCount);
      return idx;
    }

    // Read the target sheet
    var sheetPath=SHEETS[S.f];
    var sheetXml=await zip.file(sheetPath).async("string");
    var sheetDom=parser.parseFromString(sheetXml,"text/xml");

    // Helper: find or create a cell in the sheet
    function setCell(ref,value,isDate){
      var p=parseRef(ref);
      var rows=sheetDom.getElementsByTagNameNS(NS,"row");
      var targetRow=null;
      for(var i=0;i<rows.length;i++){if(+rows[i].getAttribute("r")===p.r){targetRow=rows[i];break}}
      if(!targetRow){
        // Create row
        var sd=sheetDom.getElementsByTagNameNS(NS,"sheetData")[0];
        targetRow=sheetDom.createElementNS(NS,"row");
        targetRow.setAttribute("r",""+p.r);
        // Insert in order
        var inserted=false;
        for(var i=0;i<rows.length;i++){if(+rows[i].getAttribute("r")>p.r){sd.insertBefore(targetRow,rows[i]);inserted=true;break}}
        if(!inserted)sd.appendChild(targetRow);
      }
      // Find or create cell
      var cells=targetRow.getElementsByTagNameNS(NS,"c");
      var cell=null;
      var refCol=colToNum(p.c);
      for(var i=0;i<cells.length;i++){if(cells[i].getAttribute("r")===ref){cell=cells[i];break}}
      if(!cell){
        cell=sheetDom.createElementNS(NS,"c");
        cell.setAttribute("r",ref);
        // Insert in column order
        var inserted=false;
        for(var i=0;i<cells.length;i++){
          var cr=parseRef(cells[i].getAttribute("r"));
          if(colToNum(cr.c)>refCol){targetRow.insertBefore(cell,cells[i]);inserted=true;break}
        }
        if(!inserted)targetRow.appendChild(cell);
      }
      // Remove old value
      var oldV=cell.getElementsByTagNameNS(NS,"v")[0];
      if(oldV)cell.removeChild(oldV);
      var oldIS=cell.getElementsByTagNameNS(NS,"is")[0];
      if(oldIS)cell.removeChild(oldIS);

      if(value===null||value===undefined||value==="")return;

      var v=sheetDom.createElementNS(NS,"v");
      if(isDate){
        var ds=dateSerial(value);
        if(ds===null)return;
        cell.removeAttribute("t");
        // Keep existing style or use a date style
        v.textContent=""+ds;
      }else if(typeof value==="number"){
        cell.removeAttribute("t");
        v.textContent=""+value;
      }else{
        // String: add to shared strings
        var idx=addSS(""+value);
        cell.setAttribute("t","s");
        v.textContent=""+idx;
      }
      cell.appendChild(v);
    }

    // ── Fill cells ──
    var o=FAC[S.f],md=S.md,ck=md.li.filter(function(_,i){return S.sl[i]}),ag=S.go||md.g||"";

    setCell(o.so,parseInt(md.sd)||md.sd);
    setCell(o.ln,parseInt(S.p.ln)||S.p.ln);
    setCell(o.man,S.sm);
    setCell(o.gen,ag);
    if(S.csr)setCell(o.csr,S.csr);
    if(S.ini)setCell(o.ini,S.ini);
    if(S.rd)setCell(o.rd,S.rd,true);
    if(S.cd)setCell(o.cd,S.cd,true);

    // Lines
    ck.slice(0,4).forEach(function(ln,i){
      var row=o.ls+i;
      setCell("C"+row,parseInt(ln.pg));
      setCell("E"+row,parseInt(ln.li));
      setCell("H"+row,ln.ws);
    });

    // Reasons - use line item numbers, not sequential
    REASONS.forEach(function(r){
      if(S.rs[r.k]){
        // Build line item number string from checked lines
        var nums=[];
        if(S.rl[r.k]){for(var n in S.rl[r.k]){if(S.rl[r.k][n])nums.push(+n)}}
        nums.sort();
        var numStr=nums.join(", ");
        if(numStr)setCell("A"+o.r[r.k],numStr);
        if(r.d){
          if(r.k==="mi"){
            // Write each of the 3 misc lines directly to its own row
            var baseRow=o.r[r.k]+r.doff;
            for(var ci=0;ci<3;ci++){
              var mlv=(S.ml[ci]||"").trim();
              if(mlv)setCell("B"+(baseRow+ci),mlv);
            }
          }else if(S.dt[r.k]){
            setCell("B"+(o.r[r.k]+r.doff),S.dt[r.k].trim());
          }
        }
      }
    });

    // Weight table
    if(S.rs.wt){
      S.wd.forEach(function(w,i){
        var row=32+i;
        var hasData=w.m||w.r||w.q||w.u;
        if(hasData)setCell("A"+row,i+1);
        if(w.m)setCell("C"+row,w.m);
        if(w.r)setCell("E"+row,w.r);
        if(w.q)setCell("G"+row,w.q);
        if(w.u)setCell("I"+row,w.u);
      });
    }

    // Serialize back
    var ser=new XMLSerializer();
    zip.file(sheetPath,ser.serializeToString(sheetDom));
    zip.file("xl/sharedStrings.xml",ser.serializeToString(ssDom));

    // Generate
    var out=await zip.generateAsync({type:"blob",mimeType:"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"});
    var url=URL.createObjectURL(out);
    var a=document.createElement("a");a.href=url;
    a.download="OFFSPEC-"+(S.sm||"").replace(/[^a-zA-Z0-9-]/g,"")+".xlsx";
    a.click();URL.revokeObjectURL(url);

    // ── Log to Firestore for The Lens ──
    if(FIREBASE_DB){
      try{
        var logIssues=[];
        REASONS.forEach(function(r){
          if(!S.rs[r.k])return;
          var issue={code:r.k,label:r.l};
          if(r.k==='mi'){
            issue.details=(S.ml||[]).filter(function(l){return(l||'').trim();});
          }else if(r.d&&S.dt[r.k]){
            issue.details=[S.dt[r.k].trim()];
          }
          logIssues.push(issue);
        });
        var logLines=ck.map(function(ln){
          return{item:ln.it||'',page:ln.pg||'',line:ln.li||'',wasteStream:ln.ws||'',profile:ln.ws||'',generator:ln.gn||'',containers:ln.cont||'',containerType:ln.cType||'',processCode:ln.procCD||'',weight:ln.weight||'',sample:ln.sample||''};
        });
        var docKey=[(S.sm||'none'),(md.sd||'none'),(S.p.ln||'none'),(S.f||'none')].join('_').replace(/[\/\.\#\$\[\]]/g,'-');
        FIREBASE_DB.collection('offspec_submissions').doc(docKey).set({
          timestamp:new Date().toISOString(),
          sourceType:S.p.type||'lsr',
          receivedDate:S.rd||'',
          loadNumber:S.p.ln||'',
          salesOrder:md.sd||'',
          manifest:S.sm||'',
          generator:ag||'',
          facility:S.f||'',
          csr:S.csr||'',
          initials:S.ini||'',
          lineItems:logLines,
          issues:logIssues
        });
      }catch(logErr){console.warn('Offspec log failed:',logErr);}
    }
  }catch(e){console.error(e);showToast("Error: "+e.message,"error")}
  btn.disabled=false;btn.textContent="\u2b07 Generate OFFSPEC .xlsx";
};
