  if(adminCols)adminCols.style.display=isAdmin("offspec")?"grid":"none";
  if(adminClear)adminClear.style.display=isAdmin("offspec")?"inline-block":"none";
  // Q-packet admin controls (mirror phrase pattern)
  var qpInstrAdd=document.getElementById("qpInstrAdminAdd");
  var qpKwAdd=document.getElementById("qpKwAdminAdd");
  if(qpInstrAdd)qpInstrAdd.style.display=isAdmin("offspec")?"grid":"none";
