function switchManageTab(tab){
  window._lastManageTab=tab;
  var tp=document.getElementById('tabPhrases');
  var tq=document.getElementById('tabQpacket');
  var bp=document.getElementById('tabBtnPhrases');
  var bq=document.getElementById('tabBtnQpacket');
  var activeStyle='color:#fff;border-bottom:2px solid #5b8aff;background:transparent;';
  var inactiveStyle='color:#888;border-bottom:2px solid transparent;background:transparent;';
  if(tab==='qpacket'){
    if(tp)tp.style.display='none';
    if(tq)tq.style.display='flex';
    if(bp)bp.style.cssText=bp.dataset.baseStyle+inactiveStyle;
    if(bq)bq.style.cssText=bq.dataset.baseStyle+activeStyle;
  }else{
    if(tp)tp.style.display='flex';
    if(tq)tq.style.display='none';
    if(bp)bp.style.cssText=bp.dataset.baseStyle+activeStyle;
    if(bq)bq.style.cssText=bq.dataset.baseStyle+inactiveStyle;
  }
}

function renderQpacketGuide(){
  // Code-specific instructions list
  var instrList=document.getElementById('qpInstrList');
  if(instrList){
    instrList.innerHTML='';
    var codes=Object.keys(QPACKET.instr||{}).sort();
    if(!codes.length){
      instrList.innerHTML='<div style="font-size:14px;color:#555;text-align:center;padding:12px;">No code-specific instructions yet.'+(isAdmin("offspec")?' Add one above.':'')+'</div>';
    }else{
      var ro=!isAdmin('offspec');
      codes.forEach(function(code){
        var row=document.createElement('div');
        row.style.cssText='display:grid;grid-template-columns:90px 1fr auto;align-items:center;gap:6px;padding:6px 8px;background:#0a0a0f;border:1px solid #2a2a3a;border-radius:6px;';
        var inputStyle='background:#0a0a0f;border:1px solid #3a3a5a;border-radius:4px;padding:4px 7px;color:#e0e0e0;font-family:\'JetBrains Mono\',monospace;font-size:14px;outline:none;width:100%;';
        var ci=document.createElement('input');ci.type='text';ci.value=code;ci.maxLength=10;ci.style.cssText=inputStyle+'color:#f0b429;text-align:center;font-weight:700;';ci.readOnly=true;
        var ti=document.createElement('input');ti.type='text';ti.value=QPACKET.instr[code]||'';ti.maxLength=200;ti.style.cssText=inputStyle+'color:#cfd8ff;';ti.readOnly=ro;
        ti.onchange=function(){QPACKET.instr[code]=ti.value.trim();saveQpacket();};
        var btns=document.createElement('div');btns.style.cssText='display:flex;gap:2px;';
        if(!ro){
          var rm=document.createElement('button');rm.title='Remove';rm.innerHTML='\u2715';rm.style.cssText='background:none;border:none;color:#ff5b5b;font-size:17px;cursor:pointer;padding:0 4px;';
          rm.onclick=function(){removeQpInstr(code);};
          btns.appendChild(rm);
        }
        row.appendChild(ci);row.appendChild(ti);row.appendChild(btns);
        instrList.appendChild(row);
      });
    }
  }
  // Photo trigger keywords
  var kwList=document.getElementById('qpKwList');
  if(kwList){
    kwList.innerHTML='';
    var kws=(QPACKET.kw||[]).slice();
    if(!kws.length){
      kwList.innerHTML='<div style="font-size:14px;color:#555;padding:6px;">No keywords \u2014 photo suggestions disabled.</div>';
    }else{
      kws.forEach(function(kw,i){
        var chip=document.createElement('span');
        chip.style.cssText='display:inline-flex;align-items:center;gap:6px;padding:5px 10px;background:rgba(240,160,48,0.10);border:1px solid #f0a030;border-radius:14px;color:#f0c060;font-size:14px;font-family:\'JetBrains Mono\',monospace;';
        var label=document.createElement('span');label.textContent=kw;chip.appendChild(label);
        if(isAdmin('offspec')){
          var x=document.createElement('button');x.innerHTML='\u2715';x.title='Remove';
          x.style.cssText='background:none;border:none;color:#ff5b5b;font-size:14px;cursor:pointer;padding:0 2px;line-height:1;';
          x.onclick=function(){removeQpKw(i);};
          chip.appendChild(x);
        }
        kwList.appendChild(chip);
      });
    }
  }
  // Keyword-triggered alerts list
  var alertList=document.getElementById('qpAlertList');
  if(alertList){
    alertList.innerHTML='';
    var alerts=Array.isArray(QPACKET.alerts)?QPACKET.alerts:[];
    if(!alerts.length){
      alertList.innerHTML='<div style="font-size:14px;color:#555;text-align:center;padding:12px;">No keyword alerts yet.'+(isAdmin("offspec")?' Add one above.':'')+'</div>';
    }else{
      var ro2=!isAdmin('offspec');
      alerts.forEach(function(a,i){
        var row=document.createElement('div');
        row.style.cssText='display:grid;grid-template-columns:120px 1fr auto;align-items:center;gap:6px;padding:6px 8px;background:#0a0a0f;border:1px solid #2a2a3a;border-radius:6px;';
        var inputStyle='background:#0a0a0f;border:1px solid #3a3a5a;border-radius:4px;padding:4px 7px;color:#e0e0e0;font-family:\'JetBrains Mono\',monospace;font-size:14px;outline:none;width:100%;';
        var ki=document.createElement('input');ki.type='text';ki.value=a.kw||'';ki.maxLength=40;ki.style.cssText=inputStyle+'color:#f0b429;font-weight:700;';ki.readOnly=ro2;
        var mi=document.createElement('input');mi.type='text';mi.value=a.msg||'';mi.maxLength=160;mi.style.cssText=inputStyle+'color:#ffe48a;';mi.readOnly=ro2;
        function saveAlertEdit(){QPACKET.alerts[i]={kw:(ki.value||'').trim().toLowerCase(),msg:(mi.value||'').trim()};saveQpacket();}
        ki.onchange=mi.onchange=saveAlertEdit;
        var btns=document.createElement('div');btns.style.cssText='display:flex;gap:2px;';
        if(!ro2){
          var rm=document.createElement('button');rm.title='Remove';rm.innerHTML='\u2715';
          rm.style.cssText='background:none;border:none;color:#ff5b5b;font-size:17px;cursor:pointer;padding:0 4px;';
          rm.onclick=function(){removeQpAlert(i);};
          btns.appendChild(rm);
        }
        row.appendChild(ki);row.appendChild(mi);row.appendChild(btns);
        alertList.appendChild(row);
      });
    }
  }
}

function addQpInstr(){
  if(!isAdmin('offspec')){requireAdmin('offspec',function(){addQpInstr();});return;}
  var ci=document.getElementById('newQpCodeInput');
  var ti=document.getElementById('newQpInstrInput');
  if(!ci||!ti)return;
  var code=(ci.value||'').trim();
  var txt=(ti.value||'').trim();
  if(!code){ci.focus();return;}
  if(!txt){ti.focus();return;}
  if(!QPACKET.instr)QPACKET.instr={};
  QPACKET.instr[code]=txt;
  saveQpacket();
  ci.value='';ti.value='';
  renderQpacketGuide();
  ci.focus();
}
function removeQpInstr(code){
  if(!isAdmin('offspec'))return;
  if(!QPACKET.instr)return;
  delete QPACKET.instr[code];
  saveQpacket();
  renderQpacketGuide();
}
function addQpKw(){
  if(!isAdmin('offspec')){requireAdmin('offspec',function(){addQpKw();});return;}
  var i=document.getElementById('newQpKwInput');
  if(!i)return;
  var v=(i.value||'').trim().toLowerCase();
  if(!v){i.focus();return;}
  if(!QPACKET.kw)QPACKET.kw=[];
  if(QPACKET.kw.indexOf(v)===-1)QPACKET.kw.push(v);
  saveQpacket();
  i.value='';
  renderQpacketGuide();
  i.focus();
}
function removeQpKw(i){
  if(!isAdmin('offspec'))return;
  if(!QPACKET.kw)return;
  if(i<0||i>=QPACKET.kw.length)return;
  QPACKET.kw.splice(i,1);
  saveQpacket();
  renderQpacketGuide();
}
function addQpAlert(){
  if(!isAdmin('offspec')){requireAdmin('offspec',function(){addQpAlert();});return;}
  var ki=document.getElementById('newQpAlertKwInput');
  var mi=document.getElementById('newQpAlertMsgInput');
  if(!ki||!mi)return;
  var kw=(ki.value||'').trim().toLowerCase();
  var msg=(mi.value||'').trim();
  if(!kw){ki.focus();return;}
  if(!msg){mi.focus();return;}
  if(!QPACKET.alerts)QPACKET.alerts=[];
  // dedupe: if same kw exists, update msg; else push
  var idx=-1;
  for(var n=0;n<QPACKET.alerts.length;n++){if((QPACKET.alerts[n].kw||'').toLowerCase()===kw){idx=n;break;}}
  if(idx>=0)QPACKET.alerts[idx]={kw:kw,msg:msg};
  else QPACKET.alerts.push({kw:kw,msg:msg});
  saveQpacket();
  ki.value='';mi.value='';
  renderQpacketGuide();
  ki.focus();
}
function removeQpAlert(i){
  if(!isAdmin('offspec'))return;
  if(!QPACKET.alerts)return;
  if(i<0||i>=QPACKET.alerts.length)return;
  QPACKET.alerts.splice(i,1);
  saveQpacket();
  renderQpacketGuide();
}
