    var pi=document.createElement("input");pi.type="text";pi.value=ph;pi.maxLength=80;pi.style.cssText=inputStyle+"color:#aaa;";pi.readOnly=ro;
    var ni=document.createElement("input");ni.type="text";ni.value=nc;ni.maxLength=10;ni.style.cssText=inputStyle+"color:#f0b429;text-align:center;";ni.readOnly=ro;
    function saveEdit(){MISC_PHRASES[i]={k:ki.value.trim()||ph,p:pi.value.trim(),n:ni.value.trim()};savePhrases();}
    ki.onchange=pi.onchange=ni.onchange=saveEdit;
