      btns.innerHTML=
        '<button onclick="movePhrase('+i+',-1)" title="Move up" style="background:none;border:none;color:#666;font-size:17px;cursor:pointer;padding:0 4px;">&#8593;</button>'+
        '<button onclick="movePhrase('+i+',1)" title="Move down" style="background:none;border:none;color:#666;font-size:17px;cursor:pointer;padding:0 4px;">&#8595;</button>'+
        '<button onclick="removePhrase('+i+')" title="Remove" style="background:none;border:none;color:#ff5b5b;font-size:17px;cursor:pointer;padding:0 4px;">&#10005;</button>';
