function escHtml(s){return s.replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;");}
function addPhrase(){
  if(!isAdmin("offspec")){requireAdmin("offspec",function(){addPhrase();});return;}
  var kinp=document.getElementById("newKeywordInput");
  var pinp=document.getElementById("newPhraseInput");
  var ninp=document.getElementById("newNotifInput");
  var kw=(kinp?kinp.value.trim():"");
  var ph=pinp.value.trim();
  var nc=(ninp?ninp.value.trim():"");
  if(!ph){pinp.focus();return;}
  if(!kw)kw=ph; // fall back to phrase as keyword if blank
  MISC_PHRASES.push({k:kw,p:ph,n:nc});
  savePhrases();
  if(kinp)kinp.value="";
  pinp.value="";
  if(ninp)ninp.value="";
  kinp.focus();
  renderPhraseList();
}
function removePhrase(i){
  if(!isAdmin("offspec"))return;
  MISC_PHRASES.splice(i,1);
  savePhrases();
  renderPhraseList();
}
function movePhrase(i,dir){
  if(!isAdmin("offspec"))return;
  var j=i+dir;
  if(j<0||j>=MISC_PHRASES.length)return;
  var tmp=MISC_PHRASES[i];MISC_PHRASES[i]=MISC_PHRASES[j];MISC_PHRASES[j]=tmp;
  savePhrases();
  renderPhraseList();
}
function clearAllPhrases(){
  if(!isAdmin("offspec"))return;
  if(!confirm("Clear all phrases?"))return;
  MISC_PHRASES.length=0;
  savePhrases();
  renderPhraseList();
}

// ── Create Notifications ──
function createNotifications(){
  try{
  // Gather non-empty lines (preserving index for code lookup)
  var lines = [];
  (S.ml||[]).forEach(function(l, i){
    var t = (l||'').trim();
    if(t) lines.push({text: t, code: ((S.mc||[])[i]||'').trim()});
  });
  if(!lines.length){
    showToast('No offspec lines to combine.','warn');
    return;
  }

  // Collect codes from any line that had a preset selected (even if edited)
  var notifCodes = [];
  lines.forEach(function(line){
    if(line.code) notifCodes.push(line.code);
  });

  // Title: show code if all lines that have a code share the same one
  var uniqueCodes = notifCodes.filter(function(c,i,a){return a.indexOf(c)===i;});
  var title = (notifCodes.length>0 && uniqueCodes.length===1) ? 'Use '+uniqueCodes[0] : null;

  // Build message — join with ". " and ensure final period
  var message = lines.map(function(l){return l.text.replace(/\.+$/,'');}).join('. ')+'.';

  // Auto-insert Z22 intro text when all codes are Z22
  var allZ22 = notifCodes.length>0 && uniqueCodes.length===1 && uniqueCodes[0]==='Z22';
  if(allZ22){
    message = '10% OR GREATER DISCREPANCY BETWEEN MANIFESTED AND RECEIVED WEIGHTS. ' + message;
  }

  // Show popup — no auto-copy
  showNotifPopup(title, message);
  }catch(e){showToast('Error: '+e.message,'error');}
}

function showNotifPopup(title, message){
  // Remove any existing popup
  var existing = document.getElementById('notifPopup');
  if(existing) existing.remove();

  var overlay = document.createElement('div');
  overlay.id = 'notifPopup';
  overlay.style.cssText='position:fixed;inset:0;background:rgba(0,0,0,0.7);z-index:2000;display:flex;align-items:center;justify-content:center;';

  var box = document.createElement('div');
  box.style.cssText='background:#131320;border:1px solid #2a2a3a;border-radius:12px;padding:28px 32px;max-width:520px;width:90%;box-shadow:0 8px 40px rgba(0,0,0,0.6);position:relative;';

  // Apply current theme background styling
  if(document.body.classList.contains('theme-light')) box.style.background='#ffffff';
  else if(document.body.classList.contains('theme-puke')) box.style.cssText+=';background:#fff0fb;border-color:#ff69b4;';
  else if(document.body.classList.contains('theme-gothic')) box.style.background='#1a000d';
  else if(document.body.classList.contains('theme-popart')) box.style.cssText+=';background:#fff200;border:3px solid #1a0040;';

  var html = '';

  // SO# line with item numbers — always shown
  var soVal = (document.getElementById('aso') && document.getElementById('aso').value.trim()) || '—';
  var itemNums = [];
  if(S.md && S.md.li){
    S.md.li.forEach(function(ln, i){ if(S.sl[i] && ln.it) itemNums.push(ln.it); });
  }
  var so7m=String(soVal||'').match(/\d{7}/);
  var so7=so7m?so7m[0]:String(soVal||'').trim();
  var itemSuffix=itemNums.length?(' - Item '+itemNums.join(', ')):'';
  html += '<div style="font-family:Arial,Helvetica,sans-serif;font-size:22px;font-weight:700;color:#aaa;margin-bottom:6px;display:flex;align-items:center;gap:8px;flex-wrap:wrap;">'+
    '<span>SO#'+escHtml(soVal)+'</span>'+
    (so7?'<button type="button" id="soCopyBtn" title="Copy '+escHtml(so7)+' to clipboard" style="background:transparent;border:1px solid #2a2a3a;border-radius:6px;color:#888;cursor:pointer;padding:3px 9px;font-size:14px;line-height:1;font-family:inherit;">&#128203;</button>':'')+
    (itemSuffix?'<span style="color:#888;font-weight:400;">'+escHtml(itemSuffix)+'</span>':'')+
  '</div>';

  // Notification code title — shown when all lines share a code
  if(title){
    html += '<div style="font-family:Arial,Helvetica,sans-serif;font-size:44px;font-weight:700;color:#f0b429;margin-bottom:14px;">'+escHtml(title)+'</div>';
  }

  // Message box
  html += '<div id="notifMsgText" style="font-size:17px;line-height:1.7;padding:14px 16px;border-radius:8px;background:rgba(91,138,255,0.06);border:1px solid #2a2a3a;white-space:pre-wrap;word-break:break-word;margin-bottom:18px;">'+escHtml(message)+'</div>';

  // Attachment checkboxes
  html += '<div style="display:flex;gap:20px;align-items:center;margin-bottom:14px;">';
  html += '<label style="display:flex;align-items:center;gap:6px;font-size:15px;color:#aaa;cursor:pointer;"><input type="checkbox" id="chkOffspec" style="width:16px;height:16px;cursor:pointer;"> Offspec</label>';
  html += '<label style="display:flex;align-items:center;gap:6px;font-size:15px;color:#aaa;cursor:pointer;"><input type="checkbox" id="chkPhoto" style="width:16px;height:16px;cursor:pointer;"> Photo</label>';
  html += '</div>';
  html += '<div id="attachmentLine" style="font-size:15px;color:#888;min-height:20px;margin-bottom:14px;"></div>';

  // ── Notification Guide ──
  var selLines=getSelectedLineDetails();
  var miscLines=getActiveMiscLines();
  var over10=getOver10Lines(selLines);
  var photoHits=detectPhotoTriggers(miscLines);
  var notifCodes=getCurrentNotifCodes();
  var codeInstrs={};
  notifCodes.forEach(function(c){if(QPACKET.instr&&QPACKET.instr[c])codeInstrs[c]=QPACKET.instr[c];});
  var hasGuide=over10.length||photoHits.length||Object.keys(codeInstrs).length;
  if(hasGuide){
    html += '<div style="margin-bottom:16px;padding:14px 16px;border:1px solid #2a2a3a;border-radius:8px;background:rgba(91,138,255,0.04);">';
    html += '<div style="font-family:Syne,sans-serif;font-size:14px;font-weight:700;color:#888;text-transform:uppercase;letter-spacing:1px;margin-bottom:10px;">Notification Guide</div>';
    if(over10.length){
      var items=over10.map(function(ln){return 'Item '+escHtml(ln.it)+' ('+escHtml(String(ln.cont))+')';}).join(', ');
      html += '<div style="padding:10px 12px;border-radius:6px;background:rgba(255,91,91,0.10);border-left:3px solid #ff5b5b;color:#ffb0b0;font-size:15px;line-height:1.5;margin-bottom:8px;"><strong>!</strong> Number of containers is more than 10 \u2014 does this need Q Manager review? <span style="color:#888;font-size:14px;">('+items+')</span></div>';
    }
    if(photoHits.length){
      var hitText=photoHits.map(function(h){return 'Misc line '+escHtml(String(h.idx))+' \u2192 "'+escHtml(h.trigger)+'"';}).join(', ');
      html += '<div style="padding:10px 12px;border-radius:6px;background:rgba(240,160,48,0.10);border-left:3px solid #f0a030;color:#f0c060;font-size:15px;line-height:1.5;margin-bottom:8px;"><strong>\ud83d\udcf7</strong> Inner containers, paint cans, or powder detected \u2014 suggest taking pictures to include in notification. <span style="color:#888;font-size:14px;">('+hitText+')</span></div>';
    }
    // Keyword-triggered alerts (e.g. oxidation -> add D001)
    var kwAlerts=detectKeywordAlerts(miscLines);
    // Group by message so repeated hits across misc lines collapse into one card
    var alertGroups={};
    kwAlerts.forEach(function(h){
      var key=h.kw+'\u00a7'+h.msg;
      if(!alertGroups[key])alertGroups[key]={kw:h.kw,msg:h.msg,idxs:[]};
      if(alertGroups[key].idxs.indexOf(h.idx)===-1)alertGroups[key].idxs.push(h.idx);
    });
    Object.keys(alertGroups).forEach(function(k){
      var g=alertGroups[k];
      var ctx=g.idxs.length?(' <span style="color:#888;font-size:14px;">(Misc line '+g.idxs.map(function(n){return escHtml(String(n));}).join(', ')+' \u2192 "'+escHtml(g.kw)+'")</span>'):'';
      html += '<div style="padding:10px 12px;border-radius:6px;background:rgba(240,180,41,0.10);border-left:3px solid #f0b429;color:#ffe48a;font-size:15px;line-height:1.5;margin-bottom:8px;"><strong>\u26a0</strong> '+escHtml(g.msg)+ctx+'</div>';
    });
    Object.keys(codeInstrs).forEach(function(c){
      html += '<div style="padding:10px 12px;border-radius:6px;background:rgba(91,138,255,0.10);border-left:3px solid #5b8aff;color:#cfd8ff;font-size:15px;line-height:1.5;margin-bottom:8px;"><strong>'+escHtml(c)+'</strong> Q-packet \u2014 include: <span style="color:#aab;">'+escHtml(codeInstrs[c])+'</span></div>';
    });
    html += '</div>';
  }

  // Buttons
  html += '<div style="display:flex;gap:10px;justify-content:flex-end;">';
  html += '<button id="notifCopyBtn" style="padding:14px 28px;border:none;border-radius:8px;font-size:17px;font-weight:700;cursor:pointer;background:linear-gradient(135deg,#5b8aff,#7c5bff);color:#fff;">&#128203; Copy Notification Message</button>';
  html += '<button id="notifCloseBtn" style="padding:10px 20px;border:1px solid #2a2a3a;border-radius:7px;font-size:15px;font-weight:700;cursor:pointer;background:transparent;color:#888;">Close</button>';
  html += '</div>';

  box.innerHTML = html;
  overlay.appendChild(box);
  document.body.appendChild(overlay);

  // Close handlers
  document.getElementById('notifCloseBtn').onclick = function(){overlay.remove();};
  overlay.onclick = function(e){if(e.target===overlay)overlay.remove();};

  // Attachment checkbox logic
  function updateAttachmentLine(){
    var os=document.getElementById('chkOffspec').checked;
    var ph=document.getElementById('chkPhoto').checked;
    var el=document.getElementById('attachmentLine');
    if(os&&ph) el.textContent='OFFSPEC AND PHOTO ATTACHED.';
    else if(os) el.textContent='OFFSPEC ATTACHED.';
    else if(ph) el.textContent='PHOTO ATTACHED.';
    else el.textContent='';
  }
  document.getElementById('chkOffspec').onchange=updateAttachmentLine;
  document.getElementById('chkPhoto').onchange=updateAttachmentLine;

  // SO copy button
  var soCopyBtn=document.getElementById('soCopyBtn');
  if(soCopyBtn){
    soCopyBtn.onclick=function(e){
      e.stopPropagation();
      if(!so7)return;
      navigator.clipboard.writeText(so7).then(function(){
        var orig=soCopyBtn.innerHTML,origColor=soCopyBtn.style.color;
        soCopyBtn.innerHTML='\u2713';soCopyBtn.style.color='#5bff8a';
        setTimeout(function(){soCopyBtn.innerHTML=orig;soCopyBtn.style.color=origColor;},1200);
      }).catch(function(){});
    };
  }

  // Copy and close
  document.getElementById('notifCopyBtn').onclick = function(){
    var attachLine=document.getElementById('attachmentLine').textContent;
    var fullMessage=message+(attachLine?'\n'+attachLine:'');
    navigator.clipboard.writeText(fullMessage).then(function(){
      overlay.remove();
    }).catch(function(){
      var msgEl = document.getElementById('notifMsgText');
      if(msgEl){
        var range = document.createRange();
        range.selectNodeContents(msgEl);
        var sel = window.getSelection();
        sel.removeAllRanges();
        sel.addRange(range);
      }
    });
  };
}

function updateNotifButton(){
  var btn=document.getElementById('notifBtn');
  if(!btn)return;
  btn.disabled=false;
  btn.title='Preview & copy combined offspec notification message';
}

// ── Initialize on load ──
window.addEventListener('DOMContentLoaded',function(){
  loadTheme();
  updateNotifButton();
});
